// Compiled only into the netstandard2.1 build. The project removes this file from
// every other target, the way dotnet/runtime conditions its own polyfills, so the
// rule lives in the project file and not in a #if here.
//
// This file holds only the framework APIs netstandard2.1 lacks that this project
// calls. The compiler-required types (IsExternalInit and
// CallerArgumentExpressionAttribute) are generated by PolySharp; see
// Directory.Build.props.

using System.Reflection;

namespace Hyperbee.Expressions.Internal;

/// <summary>
/// Stands in for the generic <c>MethodInfo.CreateDelegate&lt;T&gt;()</c> added in .NET 5.
/// </summary>
/// <remarks>
/// netstandard2.1 has only the non-generic overload taking a <see cref="Type"/>. On
/// targets that have the instance method it wins over this extension anyway, but the
/// shim is compiled only for netstandard so there is never a second candidate.
/// </remarks>
internal static class MethodInfoExtensions
{
    public static T CreateDelegate<T>( this MethodInfo method )
        where T : Delegate
        => (T) method.CreateDelegate( typeof( T ) );
}
